/*
 * Standalone boundary-logic harness for the CVE-2014-7826 guard change.
 * This does NOT build any kernel code; it only exercises the boolean
 * boundary condition that the candidate patch installs, to demonstrate
 * positive and vulnerability-triggering negative paths.
 */
#include <stdio.h>
#include <limits.h>

#define NR_syscalls 349

/* target pre-fix behavior: only negative numbers rejected */
static int old_guard(int syscall_nr)
{
	if (syscall_nr < 0)
		return 1; /* early return before test_bit */
	return 0;
}

/* candidate behavior: negatives and values >= NR_syscalls rejected */
static int new_guard(int syscall_nr)
{
	if (syscall_nr < 0 || syscall_nr >= NR_syscalls)
		return 1; /* early return before test_bit */
	return 0;
}

int main(void)
{
	int failures = 0;
	struct { int nr; int old_expected; int new_expected; const char *label; } cases[] = {
		{ -1, 1, 1, "negative (syscall_get_nr == -1)" },
		{ 0, 0, 0, "lower valid bound" },
		{ 348, 0, 0, "upper valid bound NR_syscalls-1" },
		{ 349, 0, 1, "first out-of-range NR_syscalls (OOB before fix)" },
		{ 1000, 0, 1, "large out-of-range" },
		{ INT_MAX, 0, 1, "INT_MAX out-of-range" },
	};
	for (unsigned i = 0; i < sizeof(cases)/sizeof(cases[0]); i++) {
		int o = old_guard(cases[i].nr);
		int n = new_guard(cases[i].nr);
		int ok = (o == cases[i].old_expected) && (n == cases[i].new_expected);
		printf("%-38s nr=%-11d old_reject=%d new_reject=%d %s\n",
		       cases[i].label, cases[i].nr, o, n, ok ? "OK" : "MISMATCH");
		if (!ok)
			failures++;
	}
	printf("failures=%d\n", failures);
	return failures ? 1 : 0;
}

